#include<bits/stdc++.h>

using namespace std;

class Diem{
	private:
		double x, y;
	public:
		Diem(){
			x = 0.0;
			y = 0.0;
		}
		friend istream& operator>>(istream &is, Diem &d){
			cout << "Nhap hoanh do x = ";
			is >> d.x;
			cout << "Nhap tung do y = ";
			is >> d.y;
			return is;
		}
		friend ostream& operator<<(ostream &os, const Diem &d){
			os << "(x, y) = (" << d.x << ", " << d.y << ")\n";
			return os;
		}
		double khoangCach(){
			return sqrt(x*x+y*y);
		}
};


int main(){
	int n;
	cout << "Nhap n: ";
	cin >> n;
	vector<Diem> d(n);

	cout << "\n=================NHAP=================\n";
	for(int i = 0; i < n; i++){
		cin >> d[i];
	}

	cout << "\n=================XUAT=================\n";
	double tongKC = 0;
	for(int i = 0; i < n; i++){
		cout << d[i];
		tongKC += d[i].khoangCach();
	}
	cout << "Tong khoang cach tu cach diem den goc toa do = " << tongKC << endl;

	cout << "\n=========DIEM CO KHOANG CACH NHO NHAT=========\n";
	double minKC = d[0].khoangCach();
	for(int i = 1; i < n; i++){
		minKC = min(minKC, d[i].khoangCach());
	}
	for(int i = 0; i < n; i++){
		if(d[i].khoangCach() == minKC){
			cout << d[i] << ", khoang cach = " << d[i].khoangCach() << endl;
		}
	}

	return 0;
}
